import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = nextInt();
        Arrays.sort(a);
        // i points at the smallest still-unmatched element; each z beats it if strictly larger
        int i = 0;
        for (int z : a) if (i < n && z > a[i]) i++;
        System.out.println(i);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func main() {
	n := readInt()
	a := make([]int, n)
	for i := range a {
		a[i] = readInt()
	}
	sort.Ints(a)
	// i points at the smallest still-unmatched element; each z beats it if strictly larger
	i := 0
	for _, z := range a {
		if i < n && z > a[i] {
			i++
		}
	}
	fmt.Println(i)
}
